import React, { useState } from 'react';
import { updateApplication, deleteApplication } from '../services/api';
import NotesModal from './NotesModal';

const statusColors = {
  'Applied': '#3b82f6',
  'Online Assessment': '#f59e0b',
  'Interview': '#8b5cf6',
  'Offer': '#10b981',
  'Rejected': '#ef4444'
};

export default function ApplicationTable({ applications, setApplications }) {
  const [selectedApp, setSelectedApp] = useState(null);

  const handleStatusChange = async (app, status) => {
    const res = await updateApplication(app.id, { ...app, status });
    setApplications(prev => prev.map(a => a.id === app.id ? res.data : a));
  };

  const handleDelete = async (id) => {
    await deleteApplication(id);
    setApplications(prev => prev.filter(a => a.id !== id));
  };

  if (applications.length === 0) return (
    <div style={styles.empty}>No applications yet. Add your first one above!</div>
  );

  return (
    <>
      <div style={styles.tableWrapper}>
        <table style={styles.table}>
          <thead>
            <tr style={styles.headerRow}>
              <th style={styles.th}>Company</th>
              <th style={styles.th}>Role</th>
              <th style={styles.th}>Status</th>
              <th style={styles.th}>Applied Date</th>
              <th style={styles.th}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {applications.map(app => (
              <tr key={app.id} style={styles.row}>
                <td style={styles.td}>{app.company}</td>
                <td style={styles.td}>{app.role}</td>
                <td style={styles.td}>
                  <select style={{...styles.statusBadge, background: statusColors[app.status] || '#666'}}
                    value={app.status} onChange={e => handleStatusChange(app, e.target.value)}>
                    <option>Applied</option>
                    <option>Online Assessment</option>
                    <option>Interview</option>
                    <option>Offer</option>
                    <option>Rejected</option>
                  </select>
                </td>
                <td style={styles.td}>{new Date(app.applied_date).toLocaleDateString()}</td>
                <td style={styles.td}>
                  <button style={styles.notesBtn} onClick={() => setSelectedApp(app)}>Notes</button>
                  <button style={styles.deleteBtn} onClick={() => handleDelete(app.id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {selectedApp && <NotesModal application={selectedApp} onClose={() => setSelectedApp(null)} />}
    </>
  );
}

const styles = {
  tableWrapper: { background: '#fff', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.08)', overflow: 'hidden' },
  table: { width: '100%', borderCollapse: 'collapse' },
  headerRow: { background: '#f8f9fa' },
  th: { padding: '0.75rem 1rem', textAlign: 'left', fontWeight: '600', color: '#444', fontSize: '0.9rem' },
  row: { borderTop: '1px solid #f0f0f0' },
  td: { padding: '0.75rem 1rem', fontSize: '0.95rem', color: '#333' },
  statusBadge: { color: '#fff', border: 'none', borderRadius: '20px', padding: '0.3rem 0.75rem', fontSize: '0.8rem', cursor: 'pointer' },
  notesBtn: { padding: '0.3rem 0.75rem', background: '#e0e7ff', color: '#4f46e5', border: 'none', borderRadius: '6px', cursor: 'pointer', marginRight: '0.5rem', fontSize: '0.85rem' },
  deleteBtn: { padding: '0.3rem 0.75rem', background: '#fee2e2', color: '#ef4444', border: 'none', borderRadius: '6px', cursor: 'pointer', fontSize: '0.85rem' },
  empty: { textAlign: 'center', padding: '3rem', color: '#999', background: '#fff', borderRadius: '12px' }
};
